import os
from pathlib import Path
from typing import Optional

from openai import OpenAI


def build_openai_client() -> OpenAI:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")
    return OpenAI(api_key=api_key)


def image_to_data_url(image_path: Optional[str] = None, image_bytes: Optional[bytes] = None, image_url: Optional[str] = None) -> str:
    if image_url:
        return image_url
    if image_bytes is None and image_path is None:
        raise ValueError("One of image_path, image_bytes, or image_url must be provided")
    if image_bytes is None and image_path is not None:
        image_bytes = Path(image_path).read_bytes()
    if image_bytes is None:
        raise ValueError("Unable to read image bytes")
    encoded = base64.b64encode(image_bytes).decode("ascii")
    return f"data:image/png;base64,{encoded}"
","vision_models.py":"import re
from dataclasses import dataclass, asdict
from typing import Any, Dict, List


def normalize_label_list(text: str) -> List[str]:
    parts = re.split(r"[\n,;•]+", text)
    cleaned = []
    seen = set()
    for part in parts:
        item = part.strip().lstrip("- ").strip()
        if not item:
            continue
        if item.lower() not in seen:
            seen.add(item.lower())
            cleaned.append(item)
    return cleaned


def normalize_text_lines(text: str) -> List[str]:
    lines = [line.strip() for line in text.splitlines()]
    return [line for line in lines if line]


def normalize_safety_label(text: str) -> str:
    lowered = text.lower()
    if any(token in lowered for token in ["unsafe", "high risk", "explicit", "violent", "hateful"]):
        return "unsafe"
    if any(token in lowered for token in ["low risk", "safe", "benign"]):
        return "safe"
    return "uncertain"


@dataclass
class LabelDetectionResult:
    labels: List[str]
    raw_text: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


@dataclass
